import{d as C,h as u,g as k,o,c as n,k as e,t as s,Z as w,$ as S,F as h,D as T,e as g,Q as m,N as x,a as I,p as D,m as A,_ as F,H as N}from"./chunks/framework.68eebb55.js";const V=l=>(D("data-v-317fabd3"),l=l(),A(),l),Q={class:"lesson"},M=m('<div class="meta" data-v-317fabd3>第 06 / 40 篇 · 第一阶段：AI 与大模型基础 · 阅读约 12–15 分钟</div><h1 data-v-317fabd3>模型推理：ChatGPT 为什么一个 Token 一个 Token 地回答？</h1><p data-v-317fabd3>上一篇我们学习了预训练、SFT 和偏好对齐。模型训练好之后，用户输入问题，它是如何在几秒钟内给出回答的？这就是 <strong data-v-317fabd3>Inference（推理）</strong>。本篇重点认识 Prefill、Decode、KV Cache、Temperature、Top-p，以及聊天产品中的流式输出。</p><h2 data-v-317fabd3>一、推理不是训练</h2><p data-v-317fabd3>训练通过梯度更新权重；普通推理使用固定的模型权重，结合当前输入预测后续 Token。你在对话里纠正一次答案，不等于模型权重立刻改变。</p><div class="visual" data-v-317fabd3><strong data-v-317fabd3>一次聊天请求的完整路径</strong><div class="step" data-v-317fabd3>用户发送消息</div><div class="arrow" data-v-317fabd3>↓</div><div class="step" data-v-317fabd3>Tokenizer → Token IDs</div><div class="arrow" data-v-317fabd3>↓</div><div class="step blue" data-v-317fabd3>Prefill：处理已有输入上下文</div><div class="arrow" data-v-317fabd3>↓</div><div class="step green" data-v-317fabd3>Decode：预测一个新 Token → 重复</div><div class="arrow" data-v-317fabd3>↓</div><div class="step" data-v-317fabd3>Token 解码为文本 → 流式显示</div></div><h2 data-v-317fabd3>二、Prefill：先读懂已经给出的上下文</h2><p data-v-317fabd3>假设用户输入「请解释 React 的 useEffect」。模型首先处理 System Prompt、历史消息与当前问题等已有输入。这个阶段称为 <strong data-v-317fabd3>Prefill</strong>，它可以对输入中的多个位置进行并行计算，并建立后续可复用的注意力缓存。</p><p data-v-317fabd3>Prefill 不等于把整段问题转换为一条人工编写的摘要；它是 Transformer 对输入序列执行计算。已有上下文越长，Prefill 通常越耗时，但性能也取决于硬件、模型结构与服务端优化。</p><h2 data-v-317fabd3>三、Decode：逐 Token 生成答案</h2><p data-v-317fabd3>Prefill 后，模型根据当前上下文预测下一个 Token。选出一个 Token 后，把它加入序列，再预测下一个。直到输出结束标记、达到长度限制或满足其他停止条件。</p><div class="visual" data-v-317fabd3><strong data-v-317fabd3>自回归解码过程</strong><div class="step" data-v-317fabd3>已有上下文：「React 是」</div><div class="arrow" data-v-317fabd3>↓ 预测</div><div class="step blue" data-v-317fabd3>生成：「一个」</div><div class="arrow" data-v-317fabd3>↓ 再预测</div><div class="step blue" data-v-317fabd3>生成：「用于」</div><div class="arrow" data-v-317fabd3>↓ 继续</div><div class="step green" data-v-317fabd3>生成：「构建 UI 的库……」</div><small data-v-317fabd3>分词结果仅为概念示意，真实 Tokenizer 不一定按这些词切分。</small></div><p data-v-317fabd3>这里的「逐 Token」指生成依赖关系，并不意味着所有推理计算都只能串行执行。模型内部的大量矩阵运算仍可并行。</p><h2 data-v-317fabd3>四、KV Cache：为什么不用每次重新计算全部历史？</h2><p data-v-317fabd3>在前面的课程中，我们知道 Attention 使用 Q、K、V。自回归解码时，过去 Token 的 K/V 在标准因果注意力中可复用。因此服务端可以保存各层历史位置的 K 和 V；生成下一个 Token 时，只计算新位置所需的表示并读取历史缓存。</p><div class="visual" data-v-317fabd3><strong data-v-317fabd3>KV Cache 的复用示意</strong><div class="step" data-v-317fabd3>Prefill：计算输入序列的 K / V</div><div class="arrow" data-v-317fabd3>↓ 保存</div><div class="step blue" data-v-317fabd3>缓存：[K₁,V₁] [K₂,V₂] [K₃,V₃]</div><div class="arrow" data-v-317fabd3>↓ 生成新 Token</div><div class="step green" data-v-317fabd3>新增 [K₄,V₄]，复用历史 K/V</div><small data-v-317fabd3>缓存按层管理；不同模型的 GQA、MQA、滑动窗口注意力和缓存策略会影响具体内存占用。</small></div><p data-v-317fabd3><strong data-v-317fabd3>代价：</strong>KV Cache 占用显存或其他存储资源，长上下文与高并发时可能成为重要瓶颈。缓存不会让注意力计算完全消失。</p><h2 data-v-317fabd3>五、Temperature：为什么同一个问题会得到不同回答？</h2><p data-v-317fabd3>模型先计算候选 Token 的 logits，再通过采样策略选择输出。Temperature（温度）会调整概率分布的平坦程度：较低温度通常更集中，较高温度通常更分散。</p><div class="formula" data-v-317fabd3>Pᵢ = softmax(logitᵢ / T)</div>',20),O={class:"visual"},E=V(()=>e("strong",null,"交互实验：Temperature 如何影响候选概率？",-1)),L={for:"temperature"},$={class:"track"},z=V(()=>e("small",null,"候选 logits 是假设数据。实际 API 的温度范围、默认值和可用性由模型提供方决定。温度趋近零时通常采用贪心式选择，但不保证整个服务完全确定。",-1)),B=m(`<h2 data-v-317fabd3>六、Top-p 与 Temperature 有什么区别？</h2><p data-v-317fabd3><strong data-v-317fabd3>Temperature</strong> 改变候选 Token 的概率分布；<strong data-v-317fabd3>Top-p（核采样）</strong> 则通常按照概率从高到低排列，只保留累计概率达到阈值 p 的最小候选集合，再从中采样。</p><table data-v-317fabd3><thead data-v-317fabd3><tr data-v-317fabd3><th data-v-317fabd3>参数</th><th data-v-317fabd3>主要作用</th></tr></thead><tbody data-v-317fabd3><tr data-v-317fabd3><td data-v-317fabd3>Temperature</td><td data-v-317fabd3>调整概率分布的集中程度</td></tr><tr data-v-317fabd3><td data-v-317fabd3>Top-p</td><td data-v-317fabd3>限制参与采样的候选集合</td></tr><tr data-v-317fabd3><td data-v-317fabd3>Max output tokens</td><td data-v-317fabd3>限制最大生成长度</td></tr></tbody></table><p data-v-317fabd3>这些参数不会直接让模型学到新知识，也不能保证消除幻觉。很多 API 建议优先调整 Temperature 或 Top-p 中的一个，而不是同时大幅修改。</p><h2 data-v-317fabd3>七、TTFT、TPS：为什么聊天机器人有时很慢？</h2><table data-v-317fabd3><thead data-v-317fabd3><tr data-v-317fabd3><th data-v-317fabd3>指标</th><th data-v-317fabd3>含义</th></tr></thead><tbody data-v-317fabd3><tr data-v-317fabd3><td data-v-317fabd3>TTFT</td><td data-v-317fabd3>Time to First Token，首个输出 Token 的等待时间</td></tr><tr data-v-317fabd3><td data-v-317fabd3>TPS</td><td data-v-317fabd3>Tokens Per Second，每秒生成 Token 数</td></tr><tr data-v-317fabd3><td data-v-317fabd3>端到端延迟</td><td data-v-317fabd3>从发起请求到完整回答结束的时间</td></tr></tbody></table><p data-v-317fabd3>TTFT 受到排队、网络、Prefill 等因素影响；TPS 受到 Decode、硬件、并发、缓存和模型大小影响。实际产品还应观察 P95/P99 延迟，而不只是平均值。</p><h2 data-v-317fabd3>八、TypeScript：如何实现流式聊天？</h2><p data-v-317fabd3>在 Node.js 后端调用支持流式输出的模型 API，前端可以逐步渲染内容，而不必等完整回答结束。以下使用 OpenAI Chat Completions 风格的示例：</p><pre data-v-317fabd3><code data-v-317fabd3>import OpenAI from &#39;openai&#39;
const client = new OpenAI()

const stream = await client.chat.completions.create({
  model: &#39;gpt-4.1-mini&#39;,
  messages: [
    { role: &#39;user&#39;, content: &#39;解释什么是 KV Cache&#39; }
  ],
  stream: true
})

for await (const chunk of stream) {
  const text = chunk.choices[0]?.delta?.content
  if (text) process.stdout.write(text)
}</code></pre><p data-v-317fabd3>这个示例在 Node.js 终端输出增量文本。真实聊天应用还需要把流传给浏览器，处理用户取消、超时、错误、内容审核和消息持久化。<strong data-v-317fabd3>流式显示不等于模型一次性生成整段回答。</strong></p><h2 data-v-317fabd3>九、工程实践：如何优化推理体验？</h2><p data-v-317fabd3>首先区分首 Token 慢还是持续生成慢。前者可以检查输入上下文长度、请求排队与 Prefill；后者检查 Decode 性能、并发和输出长度。对于业务系统，还可以采用流式渲染、合理的上下文裁剪、提示词缓存和模型分级路由。</p><p data-v-317fabd3>优化前应建立基线：记录 TTFT、TPS、错误率、每请求 Token 用量与实际费用，避免只凭体感判断性能。</p><h2 data-v-317fabd3>十、本篇总结</h2><p data-v-317fabd3><strong data-v-317fabd3>Prefill 处理已有上下文，Decode 逐步生成新 Token，KV Cache 复用历史 Key/Value；Temperature 和 Top-p 控制采样行为，流式输出改善用户等待体验。</strong></p><h2 data-v-317fabd3>十一、交互式课后测验</h2>`,17),U={class:"visual"},q=["name","checked","onChange"],G={key:0,class:"feedback"},R={class:"buttons"},j=["disabled"],H={key:0,class:"score"},J=m('<h2 data-v-317fabd3>十二、学习疑问与解答</h2><h3 data-v-317fabd3>Q1：有了 KV Cache，Attention 的计算就没有成本了吗？</h3><p data-v-317fabd3>不是。KV Cache 省去历史 K/V 的重复计算，但新 Token 仍需与可访问的历史位置计算注意力，而且缓存需要显存。</p><h3 data-v-317fabd3>Q2：Temperature 设为零，就一定得到完全相同的回答吗？</h3><p data-v-317fabd3>不一定。贪心选择降低采样随机性，但并行数值计算、服务端实现和模型版本等因素仍可能造成差异。</p><h3 data-v-317fabd3>Q3：为什么用户已经发出的完整问题不违反 Causal Mask？</h3><p data-v-317fabd3>问题在生成开始前已作为输入上下文存在；因果掩码限制的是模型在某个序列位置访问未来位置，而不是禁止它阅读用户已经提供的内容。</p><h3 data-v-317fabd3>Q4：SSE 和 Token 生成是一回事吗？</h3><p data-v-317fabd3>不是。Token 生成发生在模型推理层；SSE 等协议负责把服务端的增量事件传给浏览器。一次网络事件也不一定严格对应一个 Token。</p><footer data-v-317fabd3><a href="./05-llm-training" data-v-317fabd3>← 第 05 篇</a><a href="./" data-v-317fabd3>课程目录</a></footer>',10),Z=C({__name:"InferenceLesson",setup(l){const i=u(1),_=k(()=>{const v=[2.5,1.8,.9,.1],d=v.map(t=>Math.exp((t-Math.max(...v))/i.value)),a=d.reduce((t,p)=>t+p,0);return d.map(t=>t/a)}),r=u([]),f=u(!1),c=[{q:"Prefill 阶段主要处理什么？",opts:["整个已有输入上下文","只生成最后一个回答 Token","更新模型参数"],a:0,why:"Prefill 并行处理已有上下文并建立后续解码可复用的 KV Cache。"},{q:"Decode 阶段通常每轮生成多少新 Token？",opts:["全部答案同时生成","一个（逐步循环）","固定一千个"],a:1,why:"自回归解码每一步预测下一个 Token，随后继续下一步。"},{q:"KV Cache 主要缓存什么？",opts:["每层历史位置的 Key 和 Value","训练数据集","用户浏览器 Cookie"],a:0,why:"缓存历史 K/V，避免后续每一步都重复计算历史位置的投影。"},{q:"提高 Temperature 通常会产生什么影响？",opts:["输出分布更平坦，随机性可能增加","模型一定更准确","上下文窗口自动变长"],a:0,why:"Temperature 缩放 logits，较高温度一般让候选概率更均匀，但不保证更好。"}],P=k(()=>c.filter((v,d)=>r.value[d]===v.a).length);function y(v,d){const a=[...r.value];a[v]=d,r.value=a,f.value=!1}function K(){r.value=[],f.value=!1}return(v,d)=>(o(),n("article",Q,[M,e("div",O,[E,e("label",L,"Temperature："+s(i.value.toFixed(1)),1),w(e("input",{id:"temperature","onUpdate:modelValue":d[0]||(d[0]=a=>i.value=a),type:"range",min:"0.2",max:"2",step:"0.1"},null,512),[[S,i.value,void 0,{number:!0}]]),(o(!0),n(h,null,T(_.value,(a,t)=>(o(),n("div",{key:t,class:"probrow"},[e("span",null,s(["编程","脚本","动态","其他"][t]),1),e("div",$,[e("div",{class:"fill",style:x({width:a*100+"%"})},null,4)]),e("span",null,s((a*100).toFixed(1))+"%",1)]))),128)),z]),B,e("div",U,[(o(),n(h,null,T(c,(a,t)=>e("div",{key:t,class:"question"},[e("strong",null,s(t+1)+". "+s(a.q),1),(o(!0),n(h,null,T(a.opts,(p,b)=>(o(),n("label",{key:b,class:"option"},[e("input",{type:"radio",name:"chapter6-"+t,checked:r.value[t]===b,onChange:Y=>y(t,b)},null,40,q),I(s(p),1)]))),128)),f.value?(o(),n("p",G,s(r.value[t]===a.a?"✓ 回答正确":"正确答案："+a.opts[a.a])+"。"+s(a.why),1)):g("",!0)])),64)),e("div",R,[e("button",{disabled:c.some((a,t)=>r.value[t]===void 0),onClick:d[1]||(d[1]=a=>f.value=!0)},"提交评分",8,j),e("button",{onClick:K},"重新作答")]),f.value?(o(),n("div",H,"得分："+s(P.value)+" / "+s(c.length),1)):g("",!0)]),J]))}});const W=F(Z,[["__scopeId","data-v-317fabd3"]]),ta=JSON.parse('{"title":"06 · 模型推理：Prefill、Decode 与 KV Cache","description":"","frontmatter":{"title":"06 · 模型推理：Prefill、Decode 与 KV Cache","outline":"deep"},"headers":[],"relativePath":"guide/ai/chatbot-course/06-inference.md","filePath":"guide/ai/chatbot-course/06-inference.md","lastUpdated":1792114133000}'),X={name:"guide/ai/chatbot-course/06-inference.md"},ea=Object.assign(X,{setup(l){return(i,_)=>(o(),n("div",null,[N(W)]))}});export{ta as __pageData,ea as default};
